{"kind":"tool","id":"fXnwH6gDU9Y","toolName":"write_file","input":{"path":"lib/faculty.ts","instructions":"Add server-side faculty directory lookups backed by Postgres","content":"import "server-only";

import { FACULTY_SEARCH_LIMIT, FACULTY_SEARCH_MIN_LENGTH } from "@/lib/config";
import { sql } from "@/lib/db";
import { normalizeMaheId } from "@/lib/identifiers";
import { normalizeText } from "@/lib/text";

export type FacultyMember = {
  maheId: string;
  name: string;
  department: string;
};

type FacultyRow = { mahe_id: string; name: string; department: string };

function toMember(row: FacultyRow): FacultyMember {
  return { maheId: row.mahe_id, name: row.name, department: row.department };
}

/**
 * Directory lookup by MAHE ID. Deliberately ID-only: the attend form never lets
 * someone skip the ID, and it keeps the directory from being browsed by name.
 * Substring matching means a pasted "MAHE0023571" and a typed "23571" both land.
 */
export async function searchFaculty(rawQuery: string): Promise<FacultyMember[]> {
  const query = normalizeMaheId(rawQuery);
  if (query.length < FACULTY_SEARCH_MIN_LENGTH) return [];

  const rows = await sql<FacultyRow[]>`
    select mahe_id, name, department
    from public.faculty
    where mahe_id like ${`%${query}%`}
    order by mahe_id asc, name asc
    limit ${FACULTY_SEARCH_LIMIT}
  `;
  return rows.map(toMember);
}

/**
 * The directory's own record for a MAHE ID, so a stale or hand-edited client
 * cannot post a name or department that contradicts the roster. Returns null
 * when the ID is unknown, and then the caller keeps what the attendee sent.
 */
export async function lookupFacultyMember(
  rawMaheId: string,
  rawName?: string,
): Promise<FacultyMember | null> {
  const maheId = normalizeMaheId(rawMaheId);
